```yaml
name: Notify Dev Channel

on:
  push:
    branches: [master]
    paths:
      - src/**

jobs:
  notify:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      issues: write
      pull-requests: write
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Notify dev channel
        if: contains(github.event.head_commit.message, 'Merge pull request')
        uses: actions/github-script@v6
        with:
          script: |
            const commitMsg = github.context.payload.head_commit?.message;
            if (!commitMsg) {
              core.info('No commit message found, skipping.');
              return;
            }

            const prMatch = commitMsg.match(/Merge pull request #(\d+)/);
            if (!prMatch) {
              core.info('Merge commit does not contain a PR number, skipping.');
              return;
            }

            const prNumber = parseInt(prMatch[1], 10);
            const { owner, repo } = github.context.repo;

            // Fetch PR details
            const { data: pr } = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: prNumber
            });

            // Comment on the PR
            const prComment = `## 🧪 Your changes are now in the dev channel!

Your PR has been merged to master and is available for testing in the **dev channel**.

**Test your changes before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: \`uvx ha-mcp-dev\``;

            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number: prNumber,
              body: prComment
            });

            // Find linked issues in the PR body
            const issueRefs = [];
            const body = pr.body || '';
            const issueRegex = /(Closes|Fixes|Resolves)\s+#(\d+)/gi;
            let match;
            while ((match = issueRegex.exec(body)) !== null) {
              issueRefs.push(parseInt(match[2], 10));
            }

            // Comment on each linked issue
            for (const issueNumber of issueRefs) {
              const issueComment = `## ✅ This issue has been addressed in the dev channel!

A fix for this issue has been merged to master (PR #${prNumber}) and is available for testing...`;
              await github.rest.issues.createComment({
                owner,
                repo,
                issue_number: issueNumber,
                body: issueComment
              });
            }
          result-encoding: string
